mapper.select:
SELECT pyc.*, pypc.name as categoryName, su.nick_name as createName, (select nick_name from sys_user where sys_user.user_id= pyc.belong_employee_id) as belongEmployeeName, (select nick_name from sys_user where sys_user.user_id= pyc.follow_employee_id) as followEmployeeName, (select region_name from sys_region where region_id = pyc.country_region) as countryRegionName, (select value from sys_dictionary where id= pyc.customer_source) as customerSourceValue, (select value from sys_dictionary where id = pyc.type) as typeValue
FROM sal_yt_customer as pyc LEFT JOIN pro_yt_product_category as pypc ON pypc.id = pyc.type LEFT JOIN sys_user as su ON su.user_id = pyc.create_user WHERE pyc.is_deleted = 0
AND pyc.name LIKE CONCAT('%', #{customerName}, '%')
AND pyc.code LIKE CONCAT('%', #{code}, '%')
AND pyc.store_status LIKE CONCAT('%', #{customerStoreStatus}, '%')
AND pyc.belong_employee_id = #{belongEmployeeId}
AND pyc.follow_employee_id = #{followEmployeeId}
AND (pyc.follow_employee_id = #{belongUserId} or pyc.belong_employee_id = #{belongUserId})
AND pyc.type = #{type}
ORDER BY pyc.create_time DESC

select count(distinct id)
from sal_yt_customer
where is_deleted = 0
and (
    follow_employee_id in

        #{salesId}

